package com.ecommerce.recommendation.controller;
@org.springframework.stereotype.Component public class QueryHistoryFilter extends org.springframework.web.filter.OncePerRequestFilter {
 private final com.ecommerce.recommendation.repo.QueryHistoryRepository history;public QueryHistoryFilter(com.ecommerce.recommendation.repo.QueryHistoryRepository h){history=h;}
 protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest request,jakarta.servlet.http.HttpServletResponse response,jakarta.servlet.FilterChain chain)throws java.io.IOException,jakarta.servlet.ServletException {var wrapped=new org.springframework.web.util.ContentCachingRequestWrapper(request,16384);chain.doFilter(wrapped,response);if(response.getStatus()<400&&(request.getRequestURI().startsWith("/api/assistant")||request.getRequestURI().startsWith("/api/gift-finder")||request.getRequestURI().startsWith("/api/recommendations"))){var entry=new com.ecommerce.recommendation.model.QueryHistory();entry.id=java.util.UUID.randomUUID().toString();entry.endpoint=request.getRequestURI();entry.requestPayload=new String(wrapped.getContentAsByteArray(),java.nio.charset.StandardCharsets.UTF_8);entry.createdAt=java.time.Instant.now();var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(auth!=null&&auth.getDetails() instanceof com.ecommerce.common.Identity identity)entry.customerId=identity.customerId();history.save(entry);}}
}